SELECT DISTINCTROW First(Имена_станций_1.NAME) AS Stan_name, Имена_станций.MAIN AS NUMB1120, STAN.Year, Sum(Nz(STAN.NUST,0)) AS NUST, Sum(Nz(STAN.E,0)) AS E, Sum(Nz(STAN.EOTP,0)) AS EOTP, Sum(Nz(STAN.EUST,0)) AS EUST, Sum(Nz(STAN.Q,0)) AS Q, Sum(Nz(STAN.TUST,0)) AS TUST, Sum(Nz(STAN.B,0)) AS B, IIf([EOTP]>0,[EUST]/[EOTP]*1000,0) AS EURT, IIf([Q]>0,[TUST]/[Q]*1000,0) AS TURT, Sum(Nz(STAN.GAZ,0)) AS GAZ, Sum(Nz(STAN.ISK_GAZ,0)) AS ISK_GAZ, Sum(Nz(STAN.MAZUT,0)) AS MAZUT, Sum(Nz(STAN.TORF,0)) AS TORF, Sum(Nz(STAN.SLAN,0)) AS SLAN, Sum(Nz(STAN.PROCH,0)) AS PROCH, Sum(Nz(STAN.UGOL,0)) AS UGOL, Sum(Nz(STAN.DON,0)) AS DON, Sum(Nz(STAN.PODM,0)) AS PODM, Sum(Nz(STAN.PECH,0)) AS PECH, Sum(Nz(STAN.ARKT,0)) AS ARKT, Sum(Nz(STAN.KUZN,0)) AS KUZN, Sum(Nz(STAN.URAL,0)) AS URAL, Sum(Nz(STAN.BASHK,0)) AS BASHK, Sum(Nz(STAN.KAZAH,0)) AS KAZAH, Sum(Nz(STAN.KAN,0)) AS KAN, Sum(Nz(STAN.IRKUT,0)) AS IRKUT, Sum(Nz(STAN.HAK,0)) AS HAK, Sum(Nz(STAN.TUV,0)) AS TUV, Sum(Nz(STAN.BUR,0)) AS BUR, Sum(Nz(STAN.CHIT,0)) AS CHIT, Sum(Nz(STAN.YAKUT,0)) AS YAKUT, Sum(Nz(STAN.AMUR,0)) AS AMUR, Sum(Nz(STAN.URG,0)) AS URG, Sum(Nz(STAN.PRIM,0)) AS PRIM, Sum(Nz(STAN.MAG,0)) AS MAG, Sum(Nz(STAN.CHUKOT,0)) AS CHUKOT, Sum(Nz(STAN.SAH,0)) AS SAH, Sum(Nz(STAN.KAMCH,0)) AS KAMCH, Sum(Nz(STAN.QOTR,0)) AS QOTR, Sum(Nz(STAN.EWTP,0)) AS EWTP, Sum(Nz(STAN.NT,0)) AS NT
FROM (Имена_станций INNER JOIN Имена_станций AS Имена_станций_1 ON Имена_станций.MAIN = Имена_станций_1.NUMB) INNER JOIN Станции2024 AS STAN ON Имена_станций.NUMB = STAN.NUMB1120
GROUP BY Имена_станций.MAIN, STAN.Year
HAVING (((Имена_станций.MAIN) > 0)      AND ((STAN.Year) > 0))
ORDER BY Имена_станций.MAIN;
